def counter(max_value: int):
    number = 0
    while number <= max_value:
        yield number
        number += 1

if __name__ == "__main__":
    numbers = counter(1)
    try:
        print(next(numbers))
        print(next(numbers))
        print(next(numbers))
    except StopIteration:
        print("ran out of numbers")

